mapper.select:
SELECT COUNT(*)
FROM sys_announcement a
WHERE a.status = 1
AND a.scope = #{scope}

    AND (a.scope = 1 OR a.dept_id = #{deptId})

AND NOT EXISTS (
    SELECT 1 FROM sys_announcement_read ar
    WHERE ar.announcement_id = a.id AND ar.user_id = #{userId}
)

SELECT a.*, u.real_name as publisher_name, d.dept_name FROM sys_announcement a LEFT JOIN sys_user u ON a.publisher_id = u.id LEFT JOIN sys_department d ON a.dept_id = d.id WHERE a.status = 1 AND a.scope = #{scope}
AND (a.scope = 1 OR a.dept_id = #{deptId})
AND NOT EXISTS ( SELECT 1 FROM sys_announcement_read ar WHERE ar.announcement_id = a.id AND ar.user_id = #{userId} ) ORDER BY a.publish_time DESC
